export function boatBill(ledger: Ledger, prices: PricePoint[], boat: string, fromDay: number, toDay: number): Bill {
  const perDraw = boatBillByDraw(ledger, prices, boat, fromDay, toDay);
  const byDay = new Map<number, BillLine>();
  for (const line of perDraw.lines) {
    const existing = byDay.get(line.day);
    if (existing) {
      existing.volume += line.volume;
    } else {
      byDay.set(line.day, { day: line.day, volume: line.volume, price: line.price, pence: 0 });
    }
  }
  const lines = Array.from(byDay.values()).sort((a, b) => a.day - b.day);
  let volume = 0;
  let total = 0;
  for (const line of lines) {
    line.pence = chargeFor(line.volume, line.price);
    volume += line.volume;
    total += line.pence;
  }
  return { ...perDraw, lines, volume, total };
}

